src/rwa/AssetRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import {PoolKey} from "../token/Buyback.sol";
import {IAggregatorV3} from "./interfaces/IRwaExternal.sol";

/// The list of tokens a mandate may hold through Bursar, and the terms each one trades under.
///
/// Keyed on the token's address and nothing else. A look-alike carrying SGOV's exact name and
/// symbol lives at 0x50f1…3218; a registry that matched on either would price it. An address
/// that is not in this list is refused by every contract in the RWA lane.
///
/// Values are USDG with six decimals. Feed answers are USD with eight. The value of a raw
/// amount is raw × feed / 10^(decimals + 2): the feed prices one raw token with the
/// multiplier already inside it, so the multiplier is not applied again.
contract AssetRegistry {
    uint16 internal constant BPS = 10_000;

    struct Asset {
        address feed;
        /// Oldest feed answer a park, unpark or purchase will trade against.
        uint32 tradeStaleness;
        /// Oldest feed answer that still counts parked value toward spending power.
        uint32 valuationStaleness;
        /// Widest accepted gap between the feed, the pinned pool's mid and a caller's quote.
        uint16 bandBps;
        /// Taken off parked value before it counts as spending power.
        uint16 haircutBps;
        /// Collateral terms, published now and read by the collateral lane later.
        uint8 collateralTier;
        uint16 collateralHaircutBps;
        uint8 decimals;
        bool eligible;
        bool isStock;
        bool isTreasury;
        /// Largest single purchase, in USDG.
        uint128 perTradeCap;
        /// Most that one mandate may park in this asset, and most parked across all mandates.
        uint128 perMandateCap;
        uint128 totalCap;
        /// The one hookless v4 pool every trade in this asset goes through.
        PoolKey pool;
    }

    address public immutable settlementAsset;

    address public admin;
    address public pendingAdmin;

    mapping(address asset => Asset) private _assets;
    address[] private _list;

    event AssetSet(address indexed asset, address indexed feed, bool eligible, bool isStock, bool isTreasury);
    event AdminTransferStarted(address indexed from, address indexed to);
    event AdminTransferred(address indexed from, address indexed to);

    error NotAdmin();
    error NotPendingAdmin();
    error ZeroAddress();
    error NotRegistered(address asset);
    error FeedNot8Decimals(address feed);
    error BadBounds();
    error BadPool();

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    /// `admin_` is the timelock. The launch assets are written here so the list is live the
    /// block the registry is, with no window in which the deployer holds the pen.
    constructor(address admin_, address settlementAsset_, address[] memory initial, Asset[] memory configs) {
        if (admin_ == address(0) || settlementAsset_ == address(0)) revert ZeroAddress();
        if (initial.length != configs.length) revert BadBounds();
        admin = admin_;
        settlementAsset = settlementAsset_;
        emit AdminTransferred(address(0), admin_);
        for (uint256 i; i < initial.length; ++i) {
            _set(initial[i], configs[i]);
        }
    }

    function setAsset(address asset, Asset calldata config) external onlyAdmin {
        _set(asset, config);
    }

    function setEligible(address asset, bool eligible) external onlyAdmin {
        Asset storage a = _assets[asset];
        if (a.feed == address(0)) revert NotRegistered(asset);
        a.eligible = eligible;
        emit AssetSet(asset, a.feed, eligible, a.isStock, a.isTreasury);
    }

    function transferAdmin(address to) external onlyAdmin {
        if (to == address(0)) revert ZeroAddress();
        pendingAdmin = to;
        emit AdminTransferStarted(admin, to);
    }

    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) revert NotPendingAdmin();
        emit AdminTransferred(admin, msg.sender);
        admin = msg.sender;
        pendingAdmin = address(0);
    }

    /// Reverts for an address that was never registered. `eligible` is left to the caller,
    /// because a delisted asset still has to be valued and sold.
    function get(address asset) external view returns (Asset memory a) {
        a = _assets[asset];
        if (a.feed == address(0)) revert NotRegistered(asset);
    }

    function isRegistered(address asset) external view returns (bool) {
        return _assets[asset].feed != address(0);
    }

    function assets() external view returns (address[] memory) {
        return _list;
    }

    function poolId(address asset) external view returns (bytes32) {
        Asset storage a = _assets[asset];
        if (a.feed == address(0)) revert NotRegistered(asset);
        return keccak256(abi.encode(a.pool));
    }

    function _set(address asset, Asset memory config) private {
        if (asset == address(0) || config.feed == address(0)) revert ZeroAddress();
        if (IAggregatorV3(config.feed).decimals() != 8) revert FeedNot8Decimals(config.feed);
        if (
            config.tradeStaleness == 0 || config.valuationStaleness < config.tradeStaleness || config.bandBps == 0
                || config.bandBps >= BPS || config.haircutBps >= BPS || config.collateralHaircutBps >= BPS
        ) revert BadBounds();

        // One side of the pinned pool is the asset and the other is USDG, and it carries no hook:
        // a hook is third-party code that can reprice or refuse a trade after the guard has run.
        PoolKey memory p = config.pool;
        bool paired = (p.currency0 == asset && p.currency1 == settlementAsset)
            || (p.currency0 == settlementAsset && p.currency1 == asset);
        if (!paired || p.hooks != address(0)) revert BadPool();

        config.decimals = IERC20Metadata(asset).decimals();
        if (_assets[asset].feed == address(0)) _list.push(asset);
        _assets[asset] = config;

        emit AssetSet(asset, config.feed, config.eligible, config.isStock, config.isTreasury);
    }
}

src/rwa/PriceGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {AssetRegistry} from "./AssetRegistry.sol";
import {IAccessRegistry, IAggregatorV3, IRobinhoodStock, IStateView} from "./interfaces/IRwaExternal.sol";

/// Decides whether a registered asset can be traded or valued right now, and at what price.
///
/// A trade needs all of: a registered and eligible asset, a feed answer younger than the
/// asset's trade bound, the token's oracle and transfers unpaused, Robinhood's access registry
/// unpaused and not blocking the account, and the pinned pool's mid within the asset's band of
/// the feed. The last check is what catches a mis-scaled answer: on 2026-06-23 the AAPL, SPY and
/// NVDA feeds each published a round 1e8 too large, fresh by every timestamp test.
///
/// Valuation is softer on purpose. SGOV prices once a day and skips Sunday, so parked value
/// keeps counting up to the asset's valuation bound (100 hours covers a long weekend) and reads
/// zero after it. Valuation never reverts; it reports `fresh`.
contract PriceGuard {
    AssetRegistry public immutable registry;
    IAccessRegistry public immutable accessRegistry;
    IStateView public immutable stateView;

    uint256 internal constant BPS = 10_000;
    uint256 internal constant Q96 = 1 << 96;

    error NotEligible(address asset);
    error StalePrice(address asset, uint256 age, uint256 bound);
    error BadPrice(address asset);
    error OraclePaused(address asset);
    error TokenPaused(address asset);
    error AccessPaused();
    error Blocked(address account);
    error PoolPriceDeviation(address asset, uint256 poolPriceE8, uint256 feedPriceE8);
    error PriceOutsideBand(address asset, uint256 quotedPriceE8, uint256 feedPriceE8);

    constructor(AssetRegistry registry_, IAccessRegistry accessRegistry_, IStateView stateView_) {
        registry = registry_;
        accessRegistry = accessRegistry_;
        stateView = stateView_;
    }

    /// The feed price a trade in `asset` may use for `account`, or a named revert.
    function tradePrice(address asset, address account) public view returns (uint256 priceE8) {
        AssetRegistry.Asset memory a = registry.get(asset);
        if (!a.eligible) revert NotEligible(asset);
        return _tradePrice(asset, a, account);
    }

    /// Like `tradePrice`, for selling a position out. A delisted asset can still be sold.
    function exitPrice(address asset, address account) public view returns (uint256 priceE8) {
        return _tradePrice(asset, registry.get(asset), account);
    }

    /// Also checks a caller's quote against the feed.
    function checkQuote(address asset, address account, uint256 quotedPriceE8) external view returns (uint256 priceE8) {
        priceE8 = tradePrice(asset, account);
        AssetRegistry.Asset memory a = registry.get(asset);
        if (_deviationBps(quotedPriceE8, priceE8) > a.bandBps) revert PriceOutsideBand(asset, quotedPriceE8, priceE8);
    }

    /// Price for counting a holding. Never reverts for a registered asset.
    function valuationPrice(address asset) public view returns (uint256 priceE8, uint256 updatedAt, bool fresh) {
        AssetRegistry.Asset memory a = registry.get(asset);
        int256 answer;
        (, answer,, updatedAt,) = IAggregatorV3(a.feed).latestRoundData();
        if (answer <= 0 || updatedAt > block.timestamp) return (0, updatedAt, false);
        priceE8 = uint256(answer);
        fresh = block.timestamp - updatedAt <= a.valuationStaleness && !IRobinhoodStock(asset).oraclePaused();
    }

    /// USDG value of `raw` at the valuation price, zero when the price is not fresh.
    function valueOf(address asset, uint256 raw) external view returns (uint256 usdg, bool fresh) {
        (uint256 priceE8,, bool ok) = valuationPrice(asset);
        if (!ok) return (0, false);
        AssetRegistry.Asset memory a = registry.get(asset);
        return (Math.mulDiv(raw, priceE8, 10 ** (uint256(a.decimals) + 2)), true);
    }

    /// Mid of the asset's pinned pool, as USD per whole token with eight decimals.
    function poolPriceE8(address asset) public view returns (uint256) {
        AssetRegistry.Asset memory a = registry.get(asset);
        (uint160 sqrtPriceX96,,,) = stateView.getSlot0(keccak256(abi.encode(a.pool)));
        return midE8(sqrtPriceX96, a.pool.currency0 == asset, a.decimals);
    }

    /// `sqrtPriceX96` is token1 per token0 in raw units. USDG has six decimals.
    function midE8(uint160 sqrtPriceX96, bool assetIsCurrency0, uint8 decimals) public pure returns (uint256) {
        uint256 s = sqrtPriceX96;
        if (s == 0) return 0;
        uint256 scale = 10 ** (uint256(decimals) + 2);
        if (assetIsCurrency0) return Math.mulDiv(Math.mulDiv(s, s, Q96), scale, Q96);
        return Math.mulDiv(Math.mulDiv(Q96, Q96, s), scale, s);
    }

    function _tradePrice(address asset, AssetRegistry.Asset memory a, address account)
        private
        view
        returns (uint256 priceE8)
    {
        if (IRobinhoodStock(asset).oraclePaused()) revert OraclePaused(asset);
        if (IRobinhoodStock(asset).tokenPaused()) revert TokenPaused(asset);
        if (accessRegistry.paused()) revert AccessPaused();
        if (accessRegistry.isBlocked(account)) revert Blocked(account);

        (, int256 answer,, uint256 updatedAt,) = IAggregatorV3(a.feed).latestRoundData();
        if (answer <= 0 || updatedAt > block.timestamp) revert BadPrice(asset);
        uint256 age = block.timestamp - updatedAt;
        if (age > a.tradeStaleness) revert StalePrice(asset, age, a.tradeStaleness);
        priceE8 = uint256(answer);

        uint256 pool = poolPriceE8(asset);
        if (pool == 0 || _deviationBps(pool, priceE8) > a.bandBps) revert PoolPriceDeviation(asset, pool, priceE8);
    }

    function _deviationBps(uint256 x, uint256 ref) private pure returns (uint256) {
        uint256 diff = x > ref ? x - ref : ref - x;
        return Math.mulDiv(diff, BPS, ref, Math.Rounding.Ceil);
    }
}

src/rwa/V4Swapper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {IPoolManager, PoolKey, SwapParams} from "../token/Buyback.sol";

/// One swap against one pinned Uniswap v4 pool, paid from this contract's own balance.
///
/// Trades go straight to the PoolManager (0x8366…0951) rather than through the UniversalRouter:
/// the router would need a Permit2 allowance on every caller for a route that is always a single
/// hookless pool. Both legs are read back from the manager's delta, never inferred from the
/// request.
abstract contract V4Swapper {
    using SafeERC20 for IERC20;

    uint160 internal constant MIN_SQRT_PRICE = 4295128739;
    uint160 internal constant MAX_SQRT_PRICE = 1461446703485210103287273052203988822378723970342;

    IPoolManager public immutable poolManager;

    bool private _unlocking;

    error NotPoolManager();
    error NotUnlocking();
    error SwapShort(uint256 amountIn, uint256 amountOut);
    error SettlementShort(uint256 paid, uint256 owed);

    struct SwapOrder {
        PoolKey key;
        bool zeroForOne;
        bool exactIn;
        /// Exact input when `exactIn`, exact output otherwise.
        uint256 amount;
        /// Minimum output when `exactIn`, maximum input otherwise.
        uint256 limit;
        address to;
    }

    constructor(IPoolManager poolManager_) {
        poolManager = poolManager_;
    }

    function _swap(SwapOrder memory order) internal returns (uint256 amountIn, uint256 amountOut) {
        _unlocking = true;
        bytes memory result = poolManager.unlock(abi.encode(order));
        (amountIn, amountOut) = abi.decode(result, (uint256, uint256));
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        if (!_unlocking) revert NotUnlocking();
        _unlocking = false;

        SwapOrder memory o = abi.decode(data, (SwapOrder));
        // forge-lint: disable-start(unsafe-typecast)
        int256 delta = poolManager.swap(
            o.key,
            SwapParams({
                zeroForOne: o.zeroForOne,
                // Negative is exact input, positive exact output.
                amountSpecified: o.exactIn ? -int256(o.amount) : int256(o.amount),
                sqrtPriceLimitX96: o.zeroForOne ? MIN_SQRT_PRICE + 1 : MAX_SQRT_PRICE - 1
            }),
            ""
        );
        int256 delta0 = int256(int128(delta >> 128));
        int256 delta1 = int256(int128(delta));
        // forge-lint: disable-end

        (int256 inDelta, int256 outDelta) = o.zeroForOne ? (delta0, delta1) : (delta1, delta0);
        if (inDelta >= 0 || outDelta <= 0) revert SwapShort(0, 0);
        uint256 owed = uint256(-inDelta);
        uint256 received = uint256(outDelta);

        // A partial fill means the pool ran out of range under the order.
        if (o.exactIn) {
            if (owed != o.amount || received < o.limit) revert SwapShort(owed, received);
        } else {
            if (received != o.amount || owed > o.limit) revert SwapShort(owed, received);
        }

        (address currencyIn, address currencyOut) =
            o.zeroForOne ? (o.key.currency0, o.key.currency1) : (o.key.currency1, o.key.currency0);

        poolManager.sync(currencyIn);
        IERC20(currencyIn).safeTransfer(address(poolManager), owed);
        uint256 paid = poolManager.settle();
        if (paid < owed) revert SettlementShort(paid, owed);

        poolManager.take(currencyOut, o.to, received);

        return abi.encode(owed, received);
    }
}

